-- Apply the named Away conflict guards as HTTP 409; preserve all access and revision checks.
DO $repair$ DECLARE signature text; function_id regprocedure; original text; repaired text; BEGIN FOREACH signature IN ARRAY ARRAY['away_course_private.write_master_course(text,jsonb,bigint,text,boolean,text)','golf_safe_private.control(text,jsonb,boolean,boolean)','golf_safe_private.protect_layout()','golf_safe_private.protect_layout_score()','golf_safe_private.validate_score(jsonb,jsonb,text,integer,boolean)','public.golf_finish_awarded_event(uuid,jsonb,bigint)','public.golf_safe_away_save(text,uuid,integer,text,jsonb,bigint,boolean,text,text)'] LOOP function_id=to_regprocedure(signature);IF function_id IS NULL THEN CONTINUE;END IF;original=pg_get_functiondef(function_id);repaired=regexp_replace(original,'(errcode\s*=\s*)''40001''','\1''PT409''','gi');IF repaired IS DISTINCT FROM original THEN EXECUTE repaired;END IF;END LOOP;END $repair$;
